css:
.phone-3d-chassis { width:370px; height:760px; }
    .phone-face-front { position:absolute; inset:0; border-radius:46px; background:#ffffff; border:1px solid #d4d8df; transform:translateZ(10px); overflow:hidden; box-shadow:inset 0 0 4px rgba(0,0,0,0.1); display:flex; flex-direction:column; z-index:10; }
    .phone-top-bezel { height:50px; width:100%; display:flex; align-items:center; justify-content:center; position:relative; background:#ffffff; z-index:5; }
    .phone-speaker-grille { width:58px; height:5px; border-radius:3px; background:#94a3b8; border:1px solid #64748b; }
    .phone-camera-dot { position:absolute; right:110px; top:50%; transform:translateY(-50%); width:9px; height:9px; border-radius:50%; background:#0f172a; box-shadow:inset 0 0 2px #38bdf8; }
    .phone-sensor-dots { position:absolute; left:110px; top:50%; transform:translateY(-50%); width:6px; height:6px; border-radius:50%; background:#64748b; }
    .phone-screen-frame { flex:1; width:100%; position:relative; overflow:hidden; background:#0f172a; }
    .phone-glass-reflection { position:absolute; inset:0; background:linear-gradient(135deg, rgba(255,255,255,0.4) 0%, rgba(255,255,255,0.05) 40%, rgba(255,255,255,0) 41%, rgba(255,255,255,0.15) 100%); pointer-events:none; z-index:15; }
    .phone-bottom-bezel { height:58px; width:100%; display:flex; align-items:center; justify-content:center; position:relative; background:#ffffff; z-index:5; }
    .phone-home-button { width:64px; height:22px; border-radius:11px; border:2px solid #cbd5e1; background:linear-gradient(180deg, #f8fafc 0%, #e2e8f0 100%); box-shadow:inset 0 1px 2px rgba(0,0,0,0.08); }
    .phone-face-back { position:absolute; inset:0; border-radius:46px; background:linear-gradient(135deg, #ffffff 0%, #e2e8f0 100%); transform:rotateY(180deg) translateZ(10px); border:2px solid #cbd5e1; box-shadow:0 35px 80px rgba(0,0,0,0.6); display:flex; align-items:center; justify-content:center; }
    .phone-back-camera { width:60px; height:60px; border-radius:18px; background:#1e293b; border:3px solid #cbd5e1; box-shadow:inset 0 0 10px #000; position:absolute; top:35px; }
    .phone-side-extrusion { position:absolute; background:linear-gradient(to bottom, #f8fafc, #cbd5e1 50%, #94a3b8); border:1px solid #cbd5e1; }
    .side-edge-left { width:20px; height:680px; left:-10px; top:40px; transform:rotateY(90deg); border-radius:6px; }
    .side-edge-right { width:20px; height:680px; right:-10px; top:40px; transform:rotateY(-90deg); border-radius:6px; }
    .side-edge-top { width:290px; height:20px; left:40px; top:-10px; transform:rotateX(90deg); border-radius:6px; }
    .side-edge-bottom { width:290px; height:20px; left:40px; bottom:-10px; transform:rotateX(-90deg); border-radius:6px; }
    .side-btn { position:absolute; background:#cbd5e1; border:1px solid #94a3b8; border-radius:3px; }
    .volume-up { width:4px; height:45px; left:-4px; top:120px; }
    .volume-down { width:4px; height:45px; left:-4px; top:180px; }
    .power-btn { width:4px; height:50px; right:-4px; top:140px; }
    .bottom-port { width:40px; height:6px; border-radius:3px; background:#475569; position:absolute; left:50%; top:50%; transform:translate(-50%, -50%); }
    .phone-ambient-shadow { position:absolute; width:360px; height:740px; border-radius:60px; background:rgba(0, 0, 0, 0.45); filter:blur(28px); transform:translateZ(-60px) scale(0.95); pointer-events:none; }
